// Typed, server-safe accessors for the static Fidibo catalog.
// Data: data/catalog.json, generated by `npm run data:fidibo`.

import catalogData from "@/data/catalog.json"

export type BookType = "ebook" | "audiobook"

export type Review = {
  /** Reviewer's first name only. */
  user: string
  /** Jalali date with Persian digits, e.g. "۱۳۹۵-۱۲-۲۳". */
  date: string
  rating: number
  text: string
  likes: number
}

export type Subcategory = {
  slug: string
  title: string
}

export type Category = {
  slug: string
  title: string
  subcategories: Subcategory[]
}

export type BookColor = {
  /** "#rrggbb" */
  dominant: string
  /** Relative luminance < 0.4: use light text on it. */
  isDark: boolean
}

export type RatingDistribution = Record<"1" | "2" | "3" | "4" | "5", number>

export type Book = {
  id: number
  title: string
  type: BookType
  authors: string[]
  translators?: string[]
  narrators?: string[]
  publisher: string
  /** Price to pay, in Toman. */
  finalPrice: number
  /** Price before discount, in Toman. */
  price?: number
  discountPct?: number
  inPlus: boolean
  free: boolean
  rating: number
  ratingsCount: number
  /** Percent of ratings per star. */
  ratingDistribution: RatingDistribution
  image: string
  /** Representative cover color, for spines and page backgrounds. */
  color: BookColor
  fidiboUrl: string
  pages?: number
  durationSeconds?: number
  fileSize?: string
  published?: string
  originalTitle?: string
  printedPrice?: number
  /** Slug of the chosen top-level category. */
  categorySlug: string
  categoryTitles: string[]
  moods: string[]
  /** Description paragraphs. */
  description: string[]
  reviewsCount: number
  reviews: Review[]
}

export type CatalogLists = {
  bestsellers: number[]
  newest: number[]
  discounted: number[]
  free: number[]
  plus: number[]
  audioBestsellers: number[]
}

export type ListName = keyof CatalogLists

export type Catalog = {
  generatedAt: string
  source: string
  categories: Category[]
  books: Book[]
  lists: CatalogLists
}

const catalog = catalogData as unknown as Catalog

const booksById = new Map(catalog.books.map((book) => [book.id, book]))

const byPopularity = (a: Book, b: Book) => b.ratingsCount - a.ratingsCount

export function getAllBooks(): Book[] {
  return catalog.books
}

export function getBook(id: number | string): Book | undefined {
  return booksById.get(Number(id))
}

export function getCategories(): Category[] {
  return catalog.categories
}

export function getCategory(slug: string): Category | undefined {
  return catalog.categories.find((category) => category.slug === slug)
}

export function getBooksByCategory(slug: string): Book[] {
  return catalog.books.filter((book) => book.categorySlug === slug)
}

export function getBooksByType(type: BookType): Book[] {
  return catalog.books.filter((book) => book.type === type)
}

export function getList(name: ListName): Book[] {
  return catalog.lists[name]
    .map((id) => booksById.get(id))
    .filter((book): book is Book => book !== undefined)
}

/** Same category, same type first, most rated first. */
export function getSimilarBooks(book: Book, limit = 8): Book[] {
  return catalog.books
    .filter(
      (other) =>
        other.id !== book.id && other.categorySlug === book.categorySlug
    )
    .sort(
      (a, b) =>
        Number(b.type === book.type) - Number(a.type === book.type) ||
        byPopularity(a, b)
    )
    .slice(0, limit)
}

/** Unifies Arabic/Persian letter variants, diacritics, ZWNJ and spacing. */
export function normalizePersian(text: string): string {
  return text
    .replace(/[\u064a\u0649]/g, "\u06cc") // ي ى -> ی
    .replace(/\u0643/g, "\u06a9") // ك -> ک
    .replace(/[\u06c0\u0629]/g, "\u0647") // ۀ ة -> ه
    .replace(/[\u0623\u0625\u0622]/g, "\u0627") // أ إ آ -> ا
    .replace(/[\u064b-\u0652\u0670]/g, "") // diacritics
    .replace(/[\u200c\u200d\u200e\u200f]/g, "") // ZWNJ, ZWJ, direction marks
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase()
}

const compact = (text: string) => text.replace(/ /g, "")

const searchIndex = new Map(
  catalog.books.map((book) => [
    book.id,
    compact(
      normalizePersian(
        [
          book.title,
          ...book.authors,
          ...(book.translators ?? []),
          ...(book.narrators ?? []),
          book.publisher,
        ].join("|")
      )
    ),
  ])
)

/**
 * Matches title, authors, translators, narrators and publisher. Every query
 * word must appear; spaces are ignored so "می خواهم" finds "می‌خواهم".
 */
export function searchBooks(query: string): Book[] {
  const terms = normalizePersian(query).split(" ").filter(Boolean)
  if (terms.length === 0) return []
  return catalog.books
    .filter((book) => {
      const haystack = searchIndex.get(book.id) ?? ""
      return terms.every((term) => haystack.includes(term))
    })
    .sort(byPopularity)
}
